@@ -0,0 +1,867 @@
+<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Usage Explorer prototype</title>
+  <style>
+    :root {
+      color-scheme: dark;
+      --bg: #090b0d;
+      --surface: #0e1114;
+      --surface-2: #12161a;
+      --surface-3: #171c21;
+      --border: #2a3036;
+      --border-strong: #3b444d;
+      --text: #f4f4f5;
+      --muted: #a1a1aa;
+      --dim: #71717a;
+      --accent: #38bdf8;
+      --accent-soft: rgb(56 189 248 / 0.12);
+      --green: #34d399;
+      --orange: #f59e0b;
+      --danger: #fb7185;
+      --radius: 6px;
+      --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
+      --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
+    }
+
+    * { box-sizing: border-box; }
+
+    body {
+      margin: 0;
+      min-width: 320px;
+      background: var(--bg);
+      color: var(--text);
+      font-family: var(--font-sans);
+      font-size: 14px;
+      line-height: 1.45;
+    }
+
+    button, input, select { font: inherit; }
+    button, select { cursor: pointer; }
+    button:focus-visible, input:focus-visible, select:focus-visible, [tabindex]:focus-visible {
+      outline: 2px solid var(--accent);
+      outline-offset: 2px;
+    }
+
+    .shell { max-width: 1540px; margin: 0 auto; padding: 22px; }
+
+    .page-header {
+      display: flex;
+      align-items: flex-start;
+      justify-content: space-between;
+      gap: 24px;
+      margin-bottom: 18px;
+    }
+
+    h1, h2, h3, p { margin-top: 0; }
+    h1 { margin-bottom: 5px; font-size: 28px; line-height: 1.2; }
+    h2 { margin-bottom: 5px; font-size: 17px; }
+    h3 { margin-bottom: 5px; font-size: 14px; }
+    .subtitle, .section-copy, .meta { color: var(--muted); }
+    .subtitle { margin: 0; }
+
+    .source-state {
+      display: grid;
+      justify-items: end;
+      gap: 4px;
+      color: var(--muted);
+      font-family: var(--font-mono);
+      font-size: 12px;
+      text-align: right;
+    }
+
+    .source-state strong { color: var(--green); font-weight: 700; }
+
+    .prototype-banner {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 18px;
+      margin-bottom: 12px;
+      padding: 9px 12px;
+      border: 1px solid #55420e;
+      border-radius: var(--radius);
+      background: #191608;
+      color: #fde68a;
+      font-family: var(--font-mono);
+      font-size: 12px;
+    }
+
+    .prototype-banner strong { color: #fef3c7; }
+
+    .filter-panel {
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface);
+      margin-bottom: 12px;
+    }
+
+    .filter-grid {
+      display: grid;
+      grid-template-columns: minmax(240px, 1.35fr) repeat(3, minmax(145px, .8fr)) minmax(190px, 1.1fr) auto;
+      gap: 10px;
+      padding: 12px;
+      align-items: end;
+    }
+
+    .field { display: grid; gap: 5px; min-width: 0; }
+    .field label, .filter-label {
+      color: var(--muted);
+      font-family: var(--font-mono);
+      font-size: 11px;
+      text-transform: uppercase;
+    }
+
+    input, select, .control {
+      min-height: 38px;
+      width: 100%;
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface-2);
+      color: var(--text);
+      padding: 8px 10px;
+    }
+
+    input::placeholder { color: var(--dim); }
+    input:hover, select:hover, .control:hover { border-color: var(--border-strong); }
+
+    .range-wrap { display: grid; gap: 6px; }
+    .range-buttons { display: flex; gap: 5px; }
+    .range-button {
+      min-height: 38px;
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface-2);
+      color: var(--muted);
+      padding: 6px 10px;
+      white-space: nowrap;
+    }
+
+    .range-button:hover { color: var(--text); border-color: var(--border-strong); }
+    .range-button[aria-pressed="true"] {
+      border-color: var(--accent);
+      background: var(--accent-soft);
+      color: var(--text);
+    }
+
+    .apply-button {
+      min-height: 38px;
+      border: 1px solid var(--accent);
+      border-radius: var(--radius);
+      background: var(--accent);
+      color: #041016;
+      font-weight: 800;
+      padding: 8px 15px;
+    }
+
+    .apply-button:active, .range-button:active, .text-button:active { transform: translateY(1px); }
+
+    .filter-state {
+      display: flex;
+      align-items: center;
+      flex-wrap: wrap;
+      gap: 7px;
+      min-height: 44px;
+      padding: 8px 12px;
+      border-top: 1px solid var(--border);
+    }
+
+    .filter-label { margin-right: 2px; }
+    .chip {
+      display: inline-flex;
+      align-items: center;
+      gap: 7px;
+      min-height: 28px;
+      border: 1px solid var(--border-strong);
+      border-radius: 999px;
+      background: var(--surface-2);
+      color: var(--text);
+      padding: 4px 9px;
+      font-family: var(--font-mono);
+      font-size: 11px;
+    }
+
+    .chip button {
+      width: 18px;
+      height: 18px;
+      border: 0;
+      border-radius: 50%;
+      background: transparent;
+      color: var(--muted);
+      padding: 0;
+      line-height: 1;
+    }
+
+    .chip button:hover { color: var(--text); background: var(--surface-3); }
+    .clear-button { margin-left: auto; }
+    .text-button {
+      border: 0;
+      background: transparent;
+      color: var(--accent);
+      padding: 5px 7px;
+      font-weight: 700;
+    }
+
+    .summary-strip {
+      display: grid;
+      grid-template-columns: minmax(150px, .7fr) minmax(260px, 1.35fr) minmax(240px, 1fr) minmax(250px, 1.1fr);
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface);
+      margin-bottom: 12px;
+    }
+
+    .summary-block { padding: 13px 15px; min-width: 0; }
+    .summary-block + .summary-block { border-left: 1px solid var(--border); }
+    .summary-label {
+      display: block;
+      margin-bottom: 4px;
+      color: var(--muted);
+      font-family: var(--font-mono);
+      font-size: 11px;
+      text-transform: uppercase;
+    }
+
+    .summary-value { font-size: 21px; font-weight: 800; }
+    .summary-detail { color: var(--muted); font-size: 12px; }
+    .positive { color: var(--green); }
+    .warning { color: var(--orange); }
+
+    .metric-grid {
+      display: grid;
+      grid-template-columns: repeat(4, 1fr);
+      gap: 10px;
+      margin-bottom: 12px;
+    }
+
+    .metric-card, .panel {
+      min-width: 0;
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface);
+    }
+
+    .metric-card { padding: 13px 14px; }
+    .metric-label {
+      color: var(--muted);
+      font-family: var(--font-mono);
+      font-size: 11px;
+      text-transform: uppercase;
+    }
+    .metric-value { margin: 5px 0 3px; font: 800 23px/1.2 var(--font-mono); }
+    .metric-detail { color: var(--muted); font: 12px/1.45 var(--font-mono); }
+
+    .primary-grid {
+      display: grid;
+      grid-template-columns: minmax(0, 1.75fr) minmax(285px, .65fr);
+      gap: 10px;
+      margin-bottom: 12px;
+    }
+
+    .panel-header {
+      display: flex;
+      justify-content: space-between;
+      align-items: flex-start;
+      gap: 18px;
+      padding: 13px 14px;
+      border-bottom: 1px solid var(--border);
+    }
+
+    .panel-header p { margin: 0; color: var(--muted); font: 12px/1.45 var(--font-mono); }
+    .panel-action { white-space: nowrap; }
+
+    .chart-scroll { overflow-x: auto; padding: 16px 14px 12px; }
+    .chart {
+      display: grid;
+      grid-template-columns: 48px repeat(14, minmax(34px, 1fr));
+      grid-template-rows: repeat(4, 42px) 28px;
+      min-width: 760px;
+      height: 216px;
+      position: relative;
+    }
+
+    .gridline {
+      grid-column: 2 / -1;
+      border-top: 1px solid #252b30;
+      position: relative;
+    }
+    .gridline span {
+      position: absolute;
+      right: calc(100% + 8px);
+      top: -9px;
+      color: var(--dim);
+      font: 10px var(--font-mono);
+      white-space: nowrap;
+    }
+    .g1 { grid-row: 1; }
+    .g2 { grid-row: 2; }
+    .g3 { grid-row: 3; }
+    .g4 { grid-row: 4; }
+
+    .bar {
+      align-self: end;
+      justify-self: stretch;
+      margin: 0 4px;
+      min-height: 4px;
+      border: 0;
+      border-radius: 2px 2px 0 0;
+      background: linear-gradient(to top, #0ea5e9 0 44%, #22c55e 44% 73%, #f59e0b 73% 89%, #8b5cf6 89% 100%);
+      opacity: .88;
+      position: relative;
+    }
+    .bar:hover, .bar:focus-visible { opacity: 1; filter: brightness(1.15); }
+    .bar[aria-pressed="true"] { box-shadow: 0 0 0 2px var(--accent); }
+    .bar::after {
+      content: attr(data-label);
+      position: absolute;
+      top: calc(100% + 8px);
+      left: 50%;
+      transform: translateX(-50%);
+      color: var(--dim);
+      font: 10px var(--font-mono);
+      white-space: nowrap;
+    }
+
+    .bar:nth-of-type(even)::after { display: none; }
+
+    .legend {
+      display: flex;
+      flex-wrap: wrap;
+      gap: 12px;
+      padding: 0 14px 14px;
+      color: var(--muted);
+      font: 11px var(--font-mono);
+    }
+    .legend span::before {
+      content: "";
+      display: inline-block;
+      width: 9px;
+      height: 9px;
+      margin-right: 6px;
+      border-radius: 2px;
+      background: var(--swatch);
+    }
+
+    .driver-list { display: grid; }
+    .driver {
+      display: grid;
+      grid-template-columns: auto 1fr auto;
+      gap: 10px;
+      align-items: center;
+      padding: 11px 13px;
+      border-bottom: 1px solid var(--border);
+    }
+    .driver:last-child { border-bottom: 0; }
+    .rank { color: var(--dim); font: 11px var(--font-mono); }
+    .driver strong { display: block; font: 700 12px var(--font-mono); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+    .driver small { color: var(--muted); font: 11px var(--font-mono); }
+    .driver-value { text-align: right; font: 700 12px var(--font-mono); }
+
+    .table-panel { margin-bottom: 12px; }
+    .table-wrap { overflow-x: auto; }
+    table { width: 100%; border-collapse: collapse; min-width: 880px; }
+    th {
+      padding: 9px 12px;
+      color: var(--muted);
+      font: 11px var(--font-mono);
+      text-align: left;
+      text-transform: uppercase;
+      border-bottom: 1px solid var(--border);
+    }
+    td {
+      padding: 10px 12px;
+      border-bottom: 1px solid var(--border);
+      font: 12px var(--font-mono);
+      vertical-align: middle;
+    }
+    tbody tr:last-child td { border-bottom: 0; }
+    tbody tr:hover { background: #11161a; }
+    .num { text-align: right; font-variant-numeric: tabular-nums; }
+    .tool-tag {
+      display: inline-flex;
+      border: 1px solid currentColor;
+      border-radius: 999px;
+      padding: 2px 7px;
+      font-size: 10px;
+      color: var(--accent);
+    }
+    .tool-tag.codex { color: #e879f9; }
+    .tool-tag.hermes { color: #facc15; }
+    .model-name { color: var(--text); font-weight: 700; }
+    .muted { color: var(--muted); }
+
+    .session-button {
+      border: 0;
+      background: transparent;
+      color: var(--accent);
+      padding: 3px 0;
+      text-align: left;
+      font-family: var(--font-mono);
+      font-weight: 700;
+    }
+    .session-button:hover { text-decoration: underline; }
+
+    .pagination {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 15px;
+      padding: 10px 12px;
+      border-top: 1px solid var(--border);
+      color: var(--muted);
+      font: 11px var(--font-mono);
+    }
+    .pager-controls { display: flex; gap: 6px; }
+    .pager-controls button {
+      min-height: 30px;
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface-2);
+      color: var(--text);
+      padding: 4px 9px;
+    }
+    .pager-controls button:disabled { color: var(--dim); cursor: not-allowed; opacity: .55; }
+
+    .detail-drawer {
+      position: fixed;
+      inset: 0 0 0 auto;
+      width: min(440px, 100%);
+      z-index: 10;
+      border-left: 1px solid var(--border-strong);
+      background: #0c0f12;
+      box-shadow: -20px 0 60px rgb(0 0 0 / .45);
+      padding: 18px;
+      overflow-y: auto;
+    }
+    .detail-drawer[hidden] { display: none; }
+    .drawer-header { display: flex; justify-content: space-between; gap: 15px; border-bottom: 1px solid var(--border); padding-bottom: 13px; }
+    .close-button {
+      width: 34px;
+      height: 34px;
+      border: 1px solid var(--border);
+      border-radius: var(--radius);
+      background: var(--surface-2);
+      color: var(--text);
+    }
+    .detail-list { display: grid; grid-template-columns: 130px 1fr; gap: 10px 12px; padding: 16px 0; margin: 0; }
+    .detail-list dt { color: var(--muted); font: 11px var(--font-mono); }
+    .detail-list dd { margin: 0; font: 12px var(--font-mono); overflow-wrap: anywhere; }
+    .detail-note { border: 1px solid var(--border); border-radius: var(--radius); background: var(--surface); padding: 12px; color: var(--muted); }
+
+    .prototype-notes {
+      padding: 13px 14px;
+      color: var(--muted);
+      font-size: 12px;
+    }
+    .prototype-notes ul { margin: 7px 0 0; padding-left: 18px; }
+
+    .sr-only {
+      position: absolute;
+      width: 1px;
+      height: 1px;
+      padding: 0;
+      margin: -1px;
+      overflow: hidden;
+      clip: rect(0, 0, 0, 0);
+      white-space: nowrap;
+      border: 0;
+    }
+
+    @media (max-width: 1120px) {
+      .filter-grid { grid-template-columns: repeat(3, 1fr); }
+      .filter-grid .range-wrap { grid-column: 1 / -1; }
+      .summary-strip { grid-template-columns: repeat(2, 1fr); }
+      .summary-block:nth-child(3) { border-left: 0; border-top: 1px solid var(--border); }
+      .summary-block:nth-child(4) { border-top: 1px solid var(--border); }
+      .metric-grid { grid-template-columns: repeat(2, 1fr); }
+    }
+
+    @media (max-width: 760px) {
+      .shell { padding: 12px; }
+      .page-header { display: grid; gap: 10px; }
+      .source-state { justify-items: start; text-align: left; }
+      .prototype-banner { display: grid; gap: 4px; align-items: flex-start; }
+      .filter-grid { grid-template-columns: 1fr; }
+      .filter-grid .range-wrap { grid-column: auto; }
+      .range-buttons { overflow-x: auto; padding-bottom: 2px; }
+      .clear-button { margin-left: 0; }
+      .summary-strip, .metric-grid, .primary-grid { grid-template-columns: 1fr; }
+      .summary-block + .summary-block { border-left: 0; border-top: 1px solid var(--border); }
+      .panel-header { align-items: flex-start; }
+      .driver-list { grid-template-columns: 1fr; }
+      h1 { font-size: 24px; }
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }
+    }
+  </style>
+</head>
+<body>
+  <main class="shell">
+    <header class="page-header">
+      <div>
+        <h1>Usage Explorer</h1>
+        <p class="subtitle">Trace usage from period summary to the sessions that produced it.</p>
+      </div>
+      <div class="source-state" aria-label="Data freshness">
+        <strong>Local sources ready</strong>
+        <span>OpenCode, Codex CLI, Hermes, Cursor</span>
+        <span>Refreshed 42 seconds ago</span>
+      </div>
+    </header>
+
+    <div class="prototype-banner" role="note">
+      <span><strong>Visual prototype</strong> with deterministic sample data. Values are not production measurements.</span>
+      <span>Scope: filters, drilldown, URL state, pagination</span>
+    </div>
+
+    <section class="filter-panel" aria-labelledby="filter-heading">
+      <h2 id="filter-heading" class="sr-only">Filter usage</h2>
+      <form id="filter-form">
+        <div class="filter-grid">
+          <div class="range-wrap">
+            <span class="filter-label">Range</span>
+            <div class="range-buttons" aria-label="Quick date range">
+              <button class="range-button" type="button" data-days="7" aria-pressed="false">7d</button>
+              <button class="range-button" type="button" data-days="30" aria-pressed="true">30d</button>
+              <button class="range-button" type="button" data-days="90" aria-pressed="false">90d</button>
+              <button class="range-button" type="button" data-days="all" aria-pressed="false">All</button>
+              <button class="range-button" type="button" data-days="custom" aria-pressed="false">Dates</button>
+            </div>
+          </div>
+          <div class="field">
+            <label for="tool-filter">Tool</label>
+            <select id="tool-filter">
+              <option value="">All tools</option>
+              <option>OpenCode</option>
+              <option selected>Codex CLI</option>
+              <option>Hermes</option>
+              <option>Cursor</option>
+            </select>
+          </div>
+          <div class="field">
+            <label for="model-filter">Model</label>
+            <select id="model-filter">
+              <option value="">All models</option>
+              <option selected>gpt-5.6-sol</option>
+              <option>gpt-5.6-luna</option>
+              <option>gpt-5.5</option>
+            </select>
+          </div>
+          <div class="field">
+            <label for="project-filter">Project</label>
+            <select id="project-filter">
+              <option value="">All projects</option>
+              <option selected>agent-platform</option>
+              <option>usage-dashboard</option>
+              <option>jlpt-dojo</option>
+            </select>
+          </div>
+          <div class="field">
+            <label for="search-filter">Search sessions</label>
+            <input id="search-filter" type="search" placeholder="Title, model, or project">
+          </div>
+          <button class="apply-button" type="submit">Apply</button>
+        </div>
+        <div class="filter-state" id="active-filters" aria-live="polite">
+          <span class="filter-label">Active scope</span>
+          <span class="chip" data-filter-chip="range">Range: 30 days <button type="button" aria-label="Clear range filter">×</button></span>
+          <span class="chip" data-filter-chip="tool">Tool: Codex CLI <button type="button" aria-label="Clear tool filter">×</button></span>
+          <span class="chip" data-filter-chip="model">Model: gpt-5.6-sol <button type="button" aria-label="Clear model filter">×</button></span>
+          <span class="chip" data-filter-chip="project">Project: agent-platform <button type="button" aria-label="Clear project filter">×</button></span>
+          <button class="text-button clear-button" id="clear-all" type="button">Clear all</button>
+        </div>
+      </form>
+    </section>
+
+    <section class="summary-strip" aria-label="Selected period summary">
+      <div class="summary-block">
+        <span class="summary-label">Selected period</span>
+        <div class="summary-value">30 days</div>
+        <div class="summary-detail">Jul 16 to Aug 14</div>
+      </div>
+      <div class="summary-block">
+        <span class="summary-label">What changed</span>
+        <div class="summary-value positive">+18% token volume</div>
+        <div class="summary-detail">Compared with the previous 30 days</div>
+      </div>
+      <div class="summary-block">
+        <span class="summary-label">Top driver</span>
+        <div class="summary-value">agent-platform</div>
+        <div class="summary-detail">41% of scoped effective volume</div>
+      </div>
+      <div class="summary-block">
+        <span class="summary-label">Accounting confidence</span>
+        <div class="summary-value warning">Partial estimate</div>
+        <div class="summary-detail">6 of 8 models priced in this scope</div>
+      </div>
+    </section>
+
+    <section class="metric-grid" aria-label="Usage metrics">
+      <article class="metric-card">
+        <span class="metric-label">Total tokens</span>
+        <div class="metric-value">9.84B</div>
+        <div class="metric-detail">2.31B direct, 7.53B cached</div>
+      </article>
+      <article class="metric-card">
+        <span class="metric-label">API-equivalent cost</span>
+        <div class="metric-value">$4,216.80</div>
+        <div class="metric-detail">Partial estimate, not subscription spend</div>
+      </article>
+      <article class="metric-card">
+        <span class="metric-label">Cache share</span>
+        <div class="metric-value">76.5%</div>
+        <div class="metric-detail">Capability matched for selected sources</div>
+      </article>
+      <article class="metric-card">
+        <span class="metric-label">Sessions</span>
+        <div class="metric-value">184</div>
+        <div class="metric-detail">6.1 per day across 3 projects</div>
+      </article>
+    </section>
